83	/// Append a component to components.csv and extend residues.csv header with its name column.
84	pub fn append(
85	    residual_dir: &Path,
86	    name: &str,
87	    description: &str,
88	    status: &str,
89	    architecture_set: &str,
90	) -> Result<()> {
91	    let session = crate::storage::integrity::sessions::begin_mutation(residual_dir, false)?;
92	    append_idempotent_inner(residual_dir, name, description, status, architecture_set)?;
93	    session.commit()?;
94	    Ok(())
95	}
