85	#[derive(Debug, Clone, PartialEq, Eq)]
86	pub struct ConfigDiscovery {
87	    pub config_path: PathBuf,
88	    pub residual_dir: PathBuf,
89	    pub source: ConfigSource,
90	}
91	
92	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
93	pub enum ConfigSource {
94	    ParentStealth,
95	    InRepo,
96	    WalkUp,
97	}
98	
99	/// Discover config following search order: parent-dir stealth → in-repo → walk up (bounded at /).
100	pub fn discover_config(start: &Path) -> Result<ConfigDiscovery> {
101	    let mut base = start.to_path_buf();
102	    if base.is_file() {
103	        base.pop();
104	    }
105	
106	    // 1. Parent-dir stealth: ../residual/config.toml relative to start directory.
107	    if let Some(parent) = base.parent() {
108	        let parent_config = parent.join("residual/config.toml");
109	        if parent_config.is_file() {
110	            return Ok(ConfigDiscovery {
111	                config_path: parent_config.clone(),
112	                residual_dir: parent.join("residual"),
113	                source: ConfigSource::ParentStealth,
114	            });
115	        }
116	    }
117	
118	    // 2. In-repo: <start>/residual/config.toml
119	    let in_repo_config = base.join("residual/config.toml");
120	    if in_repo_config.is_file() {
121	        return Ok(ConfigDiscovery {
122	            config_path: in_repo_config,
123	            residual_dir: base.join("residual"),
124	            source: ConfigSource::InRepo,
125	        });
126	    }
127	
128	    // 3. Walk up from start for residual/ directory (bounded at filesystem root).
129	    let mut dir = base;
130	    loop {
131	        let candidate = dir.join("residual");
132	        if candidate.is_dir() {
133	            return Ok(ConfigDiscovery {
134	                config_path: candidate.join("config.toml"),
135	                residual_dir: candidate,
136	                source: ConfigSource::WalkUp,
137	            });
138	        }
139	        if !dir.pop() {
140	            return Ok(ConfigDiscovery {
141	                config_path: PathBuf::from("residual/config.toml"),
142	                residual_dir: PathBuf::from("residual"),
143	                source: ConfigSource::WalkUp,
144	            });
145	        }
146	    }
147	}
