149	fn git(repo_root: &Path) -> Command {
150	    let mut cmd = Command::new("git");
151	    cmd.current_dir(repo_root);
152	    cmd
153	}
154	
155	fn branch_exists(repo_root: &Path, branch: &str) -> Result<bool> {
156	    let out = git(repo_root)
157	        .args(["rev-parse", "--verify", &format!("refs/heads/{branch}")])
158	        .output()
159	        .context("git rev-parse branch")?;
160	    Ok(out.status.success())
161	}
162	
163	fn current_branch(repo_root: &Path) -> Result<String> {
164	    let out = git(repo_root)
165	        .args(["symbolic-ref", "--short", "HEAD"])
166	        .output()
167	        .context("git symbolic-ref")?;
168	    if out.status.success() {
169	        return Ok(String::from_utf8_lossy(&out.stdout).trim().to_string());
170	    }
171	    Ok("main".to_string())
172	}
173	
174	fn bootstrap_sidecar_branch(repo_root: &Path, branch: &str) -> Result<()> {
175	    let prev = current_branch(repo_root)?;
176	    let orphan_out = git(repo_root)
177	        .args(["checkout", "--orphan", branch])
178	        .output()
179	        .context("git checkout --orphan")?;
180	    if !orphan_out.status.success() {
181	        bail!(
182	            "git checkout --orphan failed: {}",
183	            String::from_utf8_lossy(&orphan_out.stderr)
184	        );
185	    }
186	
187	    // Orphan checkout retains working-tree files; write canonical empty metadata only.
188	    let residual = repo_root.join("residual");
189	    std::fs::create_dir_all(&residual)?;
190	    let header = "id,shortname,description,naive_change,outcomes,attractor_id\n";
191	    std::fs::write(residual.join("stressors.csv"), header)?;
192	
193	    git(repo_root)
194	        .args(["rm", "-rf", "--cached", "."])
195	        .output()
196	        .ok();
197	    git(repo_root)
198	        .args(["add", "-f", "residual/"])
199	        .output()
200	        .context("git add residual")?;
201	    git(repo_root)
202	        .args(["commit", "-m", "bootstrap sidecar metadata"])
203	        .output()
204	        .context("git commit sidecar bootstrap")?;
205	
206	    git(repo_root)
207	        .args(["checkout", &prev])
208	        .output()
209	        .context("git checkout previous branch")?;
210	    Ok(())
211	}
212	
213	fn materialize_branch_tree(repo_root: &Path, branch: &str) -> Result<PathBuf> {
214	    if !branch_exists(repo_root, branch)? {
215	        bootstrap_sidecar_branch(repo_root, branch)?;
216	    }
217	
218	    let checkout = repo_root
219	        .join(".git")
220	        .join("residual-sidecar-checkout");
221	    if checkout.exists() {
222	        std::fs::remove_dir_all(&checkout)
223	            .with_context(|| format!("clear {}", checkout.display()))?;
224	    }
225	    std::fs::create_dir_all(&checkout)?;
226	
227	    let list_out = git(repo_root)
228	        .args(["ls-tree", "-r", "--name-only", branch, "--", "residual/"])
229	        .output()
230	        .context("git ls-tree sidecar")?;
231	    if !list_out.status.success() {
232	        bail!(
233	            "git ls-tree failed: {}",
234	            String::from_utf8_lossy(&list_out.stderr)
235	        );
236	    }
237	
238	    let paths = String::from_utf8_lossy(&list_out.stdout);
239	    for rel in paths.lines().filter(|l| !l.is_empty()) {
240	        let show_out = git(repo_root)
241	            .args(["show", &format!("{branch}:{rel}")])
242	            .output()
243	            .with_context(|| format!("git show {branch}:{rel}"))?;
244	        if !show_out.status.success() {
245	            continue;
246	        }
247	        let dest = checkout.join(rel.strip_prefix("residual/").unwrap_or(rel));
248	        if let Some(parent) = dest.parent() {
249	            std::fs::create_dir_all(parent)?;
250	        }
251	        std::fs::write(&dest, &show_out.stdout)?;
252	    }
253	
254	    Ok(checkout)
255	}
256	
257	fn copy_dir_all(src: &Path, dst: &Path) -> Result<()> {
258	    std::fs::create_dir_all(dst)?;
259	    for entry in std::fs::read_dir(src)? {
260	        let entry = entry?;
261	        let path = entry.path();
262	        let dest = dst.join(entry.file_name());
263	        if path.is_dir() {
264	            copy_dir_all(&path, &dest)?;
265	        } else {
266	            std::fs::copy(&path, &dest)
267	                .with_context(|| format!("copy {} -> {}", path.display(), dest.display()))?;
268	        }
269	    }
270	    Ok(())
271	}
