273	/// Write materialized metadata back to the sidecar branch when enabled.
274	pub fn persist_metadata_to_branch(
275	    repo_root: &Path,
276	    branch: &str,
277	    metadata_root: &Path,
278	) -> Result<()> {
279	    if !branch_exists(repo_root, branch)? {
280	        bail!("sidecar branch {branch} does not exist");
281	    }
282	    let prev = current_branch(repo_root)?;
283	    let checkout = git(repo_root)
284	        .args(["checkout", branch])
285	        .output()
286	        .context("git checkout sidecar for persist")?;
287	    if !checkout.status.success() {
288	        bail!(
289	            "git checkout {branch} failed: {}",
290	            String::from_utf8_lossy(&checkout.stderr)
291	        );
292	    }
293	
294	    let dest = repo_root.join("residual");
295	    if dest.exists() {
296	        std::fs::remove_dir_all(&dest)
297	            .with_context(|| format!("clear {}", dest.display()))?;
298	    }
299	    copy_dir_all(metadata_root, &dest)?;
300	
301	    git(repo_root)
302	        .args(["add", "-f", "residual/"])
303	        .output()
304	        .context("git add sidecar metadata")?;
305	    let diff = git(repo_root)
306	        .args(["diff", "--cached", "--quiet"])
307	        .output()
308	        .context("git diff --cached --quiet")?;
309	    if !diff.status.success() {
310	        let commit = git(repo_root)
311	            .args([
312	                "commit",
313	                "-m",
314	                "general - sidecar: update metadata from working branch",
315	            ])
316	            .output()
317	            .context("git commit sidecar metadata")?;
318	        if !commit.status.success() {
319	            bail!(
320	                "git commit sidecar metadata failed: {}",
321	                String::from_utf8_lossy(&commit.stderr)
322	            );
323	        }
324	    }
325	
326	    let restore = git(repo_root)
327	        .args(["checkout", "-f", &prev])
328	        .output()
329	        .context("git checkout previous branch")?;
330	    if !restore.status.success() {
331	        bail!(
332	            "git checkout {prev} failed: {}",
333	            String::from_utf8_lossy(&restore.stderr)
334	        );
335	    }
336	    Ok(())
337	}
