377	pub struct WorkingTreeWarning {
378	    pub staged_paths: Vec<String>,
379	    pub policy: WorkingTreePolicy,
380	}
381	
382	/// Check working-tree policy for staged residual/ paths on working branch.
383	pub fn check_working_tree_policy(
384	    repo_root: &Path,
385	    sidecar: &SidecarConfig,
386	) -> Result<Option<WorkingTreeWarning>> {
387	    if !sidecar.enabled || sidecar.working_tree_policy == WorkingTreePolicy::Ignore {
388	        return Ok(None);
389	    }
390	
391	    let out = git(repo_root)
392	        .args(["diff", "--cached", "--name-only"])
393	        .output()
394	        .context("git diff --cached")?;
395	    if !out.status.success() {
396	        return Ok(None);
397	    }
398	
399	    let staged: Vec<String> = String::from_utf8_lossy(&out.stdout)
400	        .lines()
401	        .filter(|p| p.starts_with("residual/") || p.starts_with("residual\\"))
402	        .map(str::to_string)
403	        .collect();
404	
405	    if staged.is_empty() {
406	        return Ok(None);
407	    }
408	
409	    Ok(Some(WorkingTreeWarning {
410	        staged_paths: staged,
411	        policy: sidecar.working_tree_policy,
412	    }))
413	}
