fn copy_dir_all(src: &Path, dst: &Path) -> Result<()> {
    copy_dir_all_excluding(src, dst, &[])
}

/// Recursive copy skipping top-level entries named in `exclude` (e.g. `config.toml`,
/// which is the in-repo pointer file and must never land on the metadata branch).
fn copy_dir_all_excluding(src: &Path, dst: &Path, exclude: &[&str]) -> Result<()> {
    std::fs::create_dir_all(dst)?;
    for entry in std::fs::read_dir(src)? {
        let entry = entry?;
        let path = entry.path();
        let name = entry.file_name();
        if exclude.iter().any(|e| name == std::ffi::OsStr::new(e)) {
            continue;
        }
        let dest = dst.join(&name);
        if path.is_dir() {
            copy_dir_all(&path, &dest)?;
        } else {
            std::fs::copy(&path, &dest)
                .with_context(|| format!("copy {} -> {}", path.display(), dest.display()))?;
        }
    }
    Ok(())
}

