    let checkout = materialize_branch_tree(repo_root, &branch)?;
    std::fs::create_dir_all(dest_residual_dir)?;
    for entry in std::fs::read_dir(&checkout)? {
        let entry = entry?;
        let path = entry.path();
        let dest = dest_residual_dir.join(entry.file_name());
        if path.is_dir() {
            copy_dir_all(&path, &dest)?;
        } else {
            std::fs::copy(&path, &dest)?;
        }
    }
    Ok(branch)
}

/// Commit `src_residual_dir` (as materialized by `branch_edit`) back onto the resolved
/// metadata branch. Never creates a branch.
pub fn branch_save(
    repo_root: &Path,
    sidecar: &SidecarConfig,
    src_residual_dir: &Path,
    commit_msg: &str,
    push: bool,
) -> Result<String> {
    let branch = resolve_for_write(repo_root, sidecar)?;
    let message = if commit_msg.is_empty() {
        "general - sidecar: manual branch save"
    } else {
        commit_msg
    };
    persist_metadata_to_branch(repo_root, &branch, src_residual_dir, message)?;
    if push {
        push_branch(repo_root, &sidecar.remote, &branch)?;
    }
    Ok(branch)
}

/// Merge `from`'s metadata branch into `to`'s metadata branch (both resolved from code
/// branch names). Leaves the repo checked out on `to`'s metadata branch with conflict
/// markers if the merge doesn't fast-forward cleanly — resolve manually, there is no
/// automatic override.
pub fn branch_merge(
    repo_root: &Path,
    sidecar: &SidecarConfig,
    from_working_branch: &str,
    to_working_branch: &str,
    commit_msg: Option<&str>,
    push: bool,
) -> Result<(String, String)> {
    let from_branch = resolve_named_for_write(repo_root, sidecar, from_working_branch)?;
    let to_branch = resolve_named_for_write(repo_root, sidecar, to_working_branch)?;
    let prev = current_branch(repo_root)?;

    let checkout = git(repo_root)
        .args(["checkout", &to_branch])
        .output()
        .context("git checkout merge target")?;
    if !checkout.status.success() {
        bail!(
            "git checkout {to_branch} failed: {}",
            String::from_utf8_lossy(&checkout.stderr)
        );
    }

    let mut merge_args = vec!["merge".to_string(), from_branch.clone()];
    if let Some(msg) = commit_msg {
        merge_args.push("-m".to_string());
        merge_args.push(msg.to_string());
    }
    let merge = git(repo_root)
        .args(&merge_args)
        .output()
        .context("git merge sidecar branches")?;
    if !merge.status.success() {
        bail!(
            "git merge {from_branch} into {to_branch} failed — repo is left on '{to_branch}' with unresolved conflicts; resolve, commit, then switch back to '{prev}' manually:\n{}",
            String::from_utf8_lossy(&merge.stderr)
        );
    }

    if push {
        push_branch(repo_root, &sidecar.remote, &to_branch)?;
    }

    let restore = git(repo_root)
        .args(["checkout", &prev])
        .output()
        .context("git checkout previous branch")?;
    if !restore.status.success() {
        bail!(
            "git checkout {prev} failed: {}",
            String::from_utf8_lossy(&restore.stderr)
        );
    }
    Ok((from_branch, to_branch))
}

/// Mirror the latest commit into the current branch's resolved metadata branch, used by
/// the post-commit hook. Silent no-op (`Ok(None)`) whenever there's nothing to sync:
/// sidecar disabled, no hand-edit materialized via `branch_edit` in `config_host_dir`, or
/// (under branch-mode) the code branch was never `branch init`-ed. Never creates a branch,
/// never errors for the ordinary "this branch doesn't track residual data" case.
pub fn branch_sync_commit(
    repo_root: &Path,
    sidecar: &SidecarConfig,
    config_host_dir: &Path,
) -> Result<Option<String>> {
    if !sidecar.enabled {
        return Ok(None);
    }
    if !config_host_dir.join("stressors.csv").is_file() {
        return Ok(None);
    }
    let branch = match resolve_for_write(repo_root, sidecar) {
        Ok(b) => b,
        Err(_) => return Ok(None),
    };
    if !branch_exists(repo_root, &branch)? {
        return Ok(None);
    }

    let subject_out = git(repo_root)
        .args(["log", "-1", "--pretty=%s"])
        .output()
        .context("git log subject")?;
    let subject = String::from_utf8_lossy(&subject_out.stdout).trim().to_string();
    let hash_out = git(repo_root)
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .context("git rev-parse short hash")?;
    let short = String::from_utf8_lossy(&hash_out.stdout).trim().to_string();
    let message = format!("{subject} ({short})");

    persist_metadata_to_branch(repo_root, &branch, config_host_dir, &message)?;
    Ok(Some(branch))
}

