#[derive(Subcommand)]
pub enum BranchOp {
    /// Create the metadata branch for a code branch, forked from the trunk's tip.
    ///
    /// Idempotent — a no-op when the metadata branch already exists.
    Init {
        /// Code branch to init for (defaults to the current branch).
        #[arg(long)]
        branch: Option<String>,
    },
    /// Materialize the resolved metadata branch into residual/ beside config.toml for
    /// hand-editing. Bails with a `branch init` hint if not yet initialized.
    Edit,
    /// Commit residual/ (as materialized by `branch edit`) back onto the resolved
    /// metadata branch.
    Save {
        #[arg(long, default_value = "")]
        commit_msg: String,
        #[arg(long)]
        push: bool,
    },
    /// Merge one code branch's metadata branch into another's.
    ///
    /// Conflicts are left unresolved on the `to` metadata branch for manual resolution —
    /// there is no automatic override.
    Merge {
        from: String,
        to: String,
        #[arg(long)]
        commit_msg: Option<String>,
        #[arg(long)]
        push: bool,
    },
    /// Mirror the latest commit into the resolved metadata branch. Used by the
    /// post-commit hook; silent no-op when there's nothing to sync.
    #[command(name = "sync-commit")]
