/// Switch back to `prev` after a branch operation. Handles the case where `prev` was
/// unborn (no commits yet, e.g. bootstrapping the sidecar in a brand-new repo) — plain
/// `git checkout` refuses to switch to a branch with no commits, so that case is
/// recreated by hand instead of erroring.
fn restore_previous_branch(repo_root: &Path, prev: &str) -> Result<()> {
    // -f: the branch we're leaving may have untracked clutter (e.g. orphan checkout
    // untracks-but-doesn't-remove the previous branch's files via `rm --cached`) that a
    // plain checkout refuses to overwrite when switching back.
    let restore = git(repo_root)
        .args(["checkout", "-f", prev])
        .output()
        .context("git checkout previous branch")?;
    if restore.status.success() {
        return Ok(());
    }
    if branch_exists(repo_root, prev)? {
        bail!(
            "git checkout {prev} failed: {}",
            String::from_utf8_lossy(&restore.stderr)
        );
    }
    // prev has no commits (unborn) — recreate that state by hand.
    let symref = git(repo_root)
        .args(["symbolic-ref", "HEAD", &format!("refs/heads/{prev}")])
        .output()
        .context("git symbolic-ref restore unborn branch")?;
    if !symref.status.success() {
        bail!(
            "restoring unborn branch {prev} failed: {}",
            String::from_utf8_lossy(&symref.stderr)
        );
    }
    git(repo_root).args(["rm", "-rf", "--cached", "."]).output().ok();
    let residual = repo_root.join("residual");
    if residual.exists() {
        std::fs::remove_dir_all(&residual).ok();
    }
    Ok(())
}

