/// Write materialized metadata back to the sidecar branch when enabled.
///
/// `metadata_root` is copied onto the branch's `residual/` tree verbatim except for a
/// top-level `config.toml` — that's the in-repo pointer file and never belongs on the
/// metadata branch itself.
pub fn persist_metadata_to_branch(
    repo_root: &Path,
    branch: &str,
    metadata_root: &Path,
    message: &str,
) -> Result<()> {
    if !branch_exists(repo_root, branch)? {
        bail!("sidecar branch {branch} does not exist");
    }
    let prev = current_branch(repo_root)?;

    // Stage a copy before switching branches: metadata_root aliases the branch's own
    // residual/ working-tree path (repo_root/residual) whenever config_host = "repo" and
    // the caller is branch_save/branch_sync_commit, so read metadata_root fully before
    // the checkout below replaces that same path with the branch's committed tree.
    let staging = repo_root.join(".git").join("residual-persist-staging");
    if staging.exists() {
        std::fs::remove_dir_all(&staging)
            .with_context(|| format!("clear {}", staging.display()))?;
    }
    copy_dir_all_excluding(metadata_root, &staging, &["config.toml"])?;

    let checkout = git(repo_root)
        .args(["checkout", "-f", branch])
        .output()
        .context("git checkout sidecar for persist")?;
    if !checkout.status.success() {
        bail!(
            "git checkout {branch} failed: {}",
            String::from_utf8_lossy(&checkout.stderr)
        );
    }

    let dest = repo_root.join("residual");
    if dest.exists() {
        std::fs::remove_dir_all(&dest)
            .with_context(|| format!("clear {}", dest.display()))?;
    }
    copy_dir_all(&staging, &dest)?;
    std::fs::remove_dir_all(&staging).ok();

    git(repo_root)
        .args(["add", "-f", "residual/"])
        .output()
        .context("git add sidecar metadata")?;
    let diff = git(repo_root)
        .args(["diff", "--cached", "--quiet"])
        .output()
        .context("git diff --cached --quiet")?;
    if !diff.status.success() {
        let commit = git(repo_root)
            .args(["commit", "-m", message])
            .output()
            .context("git commit sidecar metadata")?;
        if !commit.status.success() {
            bail!(
                "git commit sidecar metadata failed: {}",
                String::from_utf8_lossy(&commit.stderr)
            );
        }
    }

    restore_previous_branch(repo_root, &prev)?;
    Ok(())
}

