213	fn materialize_branch_tree(repo_root: &Path, branch: &str) -> Result<PathBuf> {
214	    if !branch_exists(repo_root, branch)? {
215	        bootstrap_sidecar_branch(repo_root, branch)?;
216	    }
217	
218	    let checkout = repo_root
219	        .join(".git")
220	        .join("residual-sidecar-checkout");
221	    if checkout.exists() {
222	        std::fs::remove_dir_all(&checkout)
223	            .with_context(|| format!("clear {}", checkout.display()))?;
224	    }
225	    std::fs::create_dir_all(&checkout)?;
226	
227	    let list_out = git(repo_root)
228	        .args(["ls-tree", "-r", "--name-only", branch, "--", "residual/"])
229	        .output()
230	        .context("git ls-tree sidecar")?;
231	    if !list_out.status.success() {
232	        bail!(
233	            "git ls-tree failed: {}",
234	            String::from_utf8_lossy(&list_out.stderr)
235	        );
236	    }
237	
238	    let paths = String::from_utf8_lossy(&list_out.stdout);
239	    for rel in paths.lines().filter(|l| !l.is_empty()) {
240	        let show_out = git(repo_root)
241	            .args(["show", &format!("{branch}:{rel}")])
242	            .output()
243	            .with_context(|| format!("git show {branch}:{rel}"))?;
244	        if !show_out.status.success() {
245	            continue;
246	        }
247	        let dest = checkout.join(rel.strip_prefix("residual/").unwrap_or(rel));
248	        if let Some(parent) = dest.parent() {
249	            std::fs::create_dir_all(parent)?;
250	        }
251	        std::fs::write(&dest, &show_out.stdout)?;
252	    }
253	
254	    Ok(checkout)
255	}
